-- Replace the H1 classification card with the fully audited, deeply expandable tree.
-- This affects only the REVIEW knowledge card; the independent class-quiz site is untouched.

update public.chem_knowledge_cards
set structured_content = $classification${"version":4,"intro":"先看完整分类总树，再按需要逐层展开。每一个标签都必须回答两个问题：按什么标准分，以及为什么这个物质符合定义。","overview":["第一刀只数样品中有几种物质：一种是纯净物，两种或以上是混合物。","纯净物再按所含元素种类分为单质和化合物；化合物再分有机化合物和无机化合物。","无机化合物中的氧化物、酸、碱、盐都能继续分类；元数、强弱、溶解性、含氧与否等是彼此独立的分类轴。","电解质与非电解质是只针对化合物的横向分类；要看物质本身在水溶液中或熔融状态能否产生可自由移动的离子。","同一种物质可以同时拥有多个标签，但同一次判断必须始终使用题目指定的同一分类标准。"],"rootTree":{"label":"物质","rule":"第一步只问：这份样品中实际含有几种物质？","examples":["空气含N₂、O₂等多种物质，是混合物。","液氯只含Cl₂一种物质，是纯净物。"],"children":[{"label":"混合物","rule":"由两种或两种以上物质混合而成，组成通常不固定，各成分仍保持各自性质。","examples":["空气、盐酸、氯水、食盐水","石灰乳、漂白粉、油水混合物"],"children":[{"label":"分散系","rule":"一种或多种物质分散在另一种物质中形成的混合体系。","examples":["NaCl水溶液、Fe(OH)₃胶体","泥水、石灰乳、油水混合物"],"children":[{"label":"溶液","rule":"分散质粒子直径通常小于1 nm，均一、透明、稳定。","examples":["NaCl溶液、蔗糖溶液"]},{"label":"胶体","rule":"分散质粒子直径通常为1～100 nm，能产生丁达尔效应。","examples":["Fe(OH)₃胶体、淀粉胶体、雾"]},{"label":"浊液","rule":"分散质粒子直径通常大于100 nm，常会沉降或分层。","examples":["泥水、石灰乳、油水混合物"]}]}]},{"label":"纯净物","rule":"只由一种物质组成，有确定的组成和性质。","examples":["液氯Cl₂、蒸馏水H₂O","氧化钠Na₂O、碳酸钠Na₂CO₃"],"children":[{"label":"单质","rule":"由同一种元素组成的纯净物。","examples":["金属单质：Fe、Cu、Na","非金属单质：O₂、Cl₂、S、He"],"children":[{"label":"金属单质","rule":"由金属元素组成，常具有金属光泽、导电性和延展性。","examples":["Fe、Cu、Na","Al、Mg、Zn"]},{"label":"非金属单质","rule":"由非金属元素组成，物态和性质差异较大。","examples":["O₂、Cl₂、S","H₂、N₂、He"]}],"caution":"O₂和O₃混在一起虽只含氧元素，但含两种物质，仍是混合物。"},{"label":"化合物","rule":"由两种或两种以上元素组成的纯净物。","examples":["H₂O、CO₂、NaCl","H₂SO₄、NaOH、Na₂CO₃"],"children":[{"label":"有机化合物","rule":"高中阶段通常研究含碳骨架的有机物，但含碳化合物不一定都是有机物。","examples":["CH₄、C₂H₅OH、CH₃COOH","葡萄糖C₆H₁₂O₆、乙酸乙酯CH₃COOC₂H₅"],"caution":"CO、CO₂、H₂CO₃及碳酸盐等通常仍归入无机化合物。"},{"label":"无机化合物","rule":"基础阶段继续按组成和电离特征分为氧化物、酸、碱、盐；四个入口都还能继续展开。","examples":["CO₂、HCl、Ca(OH)₂、Na₂CO₃","Na₂O、H₂SO₄、NaOH、NH₄Cl"],"children":[{"label":"氧化物","rule":"只由两种元素组成，且其中一种是氧元素；确认定义后再沿三条彼此独立的横向轴分类。","examples":["CO₂、Na₂O、Al₂O₃","CO、NO、Na₂O₂"],"children":[{"label":"分类1｜按另一种元素","rule":"分为金属氧化物和非金属氧化物。","examples":["Na₂O、Al₂O₃是金属氧化物","CO₂、CO是非金属氧化物"]},{"label":"分类2｜按酸碱性质","rule":"分为酸性、碱性、两性和不成盐氧化物。","examples":["CO₂酸性、Na₂O碱性","Al₂O₃两性、CO不成盐"]},{"label":"分类3｜按氧的特殊价态","rule":"普通氧化物中O通常为−2价；过氧化物中O为−1价。","examples":["Na₂O与CO₂是普通氧化物","Na₂O₂与H₂O₂是过氧化物"]}]},{"label":"酸","rule":"在水溶液中电离时生成的阳离子全部是H⁺；本树先列常见无机酸，再按三条独立轴分类。","examples":["HCl、H₂SO₄、HNO₃","H₂CO₃、H₃PO₄、H₂S"],"children":[{"label":"分类1｜按可电离H⁺数","rule":"分为一元酸、二元酸和多元酸；数可电离H，不能机械数化学式中的全部H。","examples":["HCl、HNO₃是一元酸","H₂SO₄、H₂CO₃是二元酸；H₃PO₄是三元酸"]},{"label":"分类2｜按电离程度","rule":"分为强酸和弱酸；强弱不等于浓稀。","examples":["HCl、HNO₃、H₂SO₄是常见强酸","H₂CO₃、H₃PO₄、H₂S是弱酸"]},{"label":"分类3｜按是否含氧","rule":"分为含氧酸和无氧酸；含氧与否不能推出强弱或元数。","examples":["HNO₃、H₂SO₄、H₂CO₃是含氧酸","HCl、HBr、H₂S是无氧酸"]}]},{"label":"碱","rule":"在水溶液中电离时生成的阴离子全部是OH⁻；元数、强弱和溶解性必须分别判断。","examples":["NaOH、KOH、Ba(OH)₂","Ca(OH)₂、Cu(OH)₂、Fe(OH)₃"],"children":[{"label":"分类1｜按可产生OH⁻数","rule":"分为一元、二元和三元等；Al(OH)₃应优先识别两性边界。","examples":["NaOH、KOH是一元碱","Ca(OH)₂、Ba(OH)₂是二元碱；Fe(OH)₃可作三元碱例"]},{"label":"分类2｜按电离程度","rule":"分为强碱和弱碱；强弱不由溶解度直接决定。","examples":["NaOH、KOH、Ba(OH)₂是强碱","NH₃·H₂O、Cu(OH)₂、Fe(OH)₃按弱碱处理"]},{"label":"分类3｜按溶解性","rule":"分为易溶、微溶和难溶碱。","examples":["NaOH、KOH、Ba(OH)₂易溶","Ca(OH)₂微溶；Mg(OH)₂、Cu(OH)₂难溶"]}]},{"label":"盐","rule":"由金属阳离子或NH₄⁺与酸根阴离子构成；组成分类和溶解性分类是两条独立轴。","examples":["NaCl、Na₂CO₃、KNO₃","NH₄Cl、NaHCO₃、Cu₂(OH)₂CO₃"],"children":[{"label":"分类1｜按组成","rule":"分为正盐、酸式盐和碱式盐。","examples":["NaCl、Na₂SO₄是正盐","NaHCO₃、NaHSO₄是酸式盐；Cu₂(OH)₂CO₃是碱式盐"]},{"label":"分类2｜按溶解性","rule":"分为可溶、微溶和难溶盐；溶解性不等于电解质强弱。","examples":["NaCl、KNO₃可溶，CaSO₄微溶","AgCl、BaSO₄、CaCO₃难溶"]}]}]},{"label":"横向轴｜电解质与非电解质","rule":"这条分类只针对化合物，与有机/无机主树交叉；判断物质本身能否在水溶液中或熔融状态产生可移动离子。","examples":["HCl、NaOH、NaCl、H₂O是电解质","蔗糖、乙醇、CO₂、NH₃是非电解质"],"children":[{"label":"电解质","rule":"在水溶液中或熔融状态，能由自身产生可自由移动离子并导电的化合物。","examples":["HCl、NaOH、NaCl","BaSO₄虽难溶仍是电解质"]},{"label":"非电解质","rule":"在水溶液中和熔融状态都不能由自身产生可自由移动离子的化合物。","examples":["蔗糖、乙醇","CO₂、SO₂、NH₃"]},{"label":"退出这组分类","rule":"单质和混合物既不是电解质，也不是非电解质。","examples":["Cu、石墨是单质","盐酸、食盐水是混合物"]}]}]}]}]},"sections":[{"title":"常见无机化合物：四个入口都可以继续展开","summary":"先用定义确认氧化物、酸、碱、盐，再进入各自的分类轴。","items":[{"label":"氧化物","rule":"只由两种元素组成，且其中一种是氧元素。确认后还可按组成元素、酸碱性质和氧的特殊价态继续分类。","examples":["CO₂、SO₃：非金属氧化物，同时是酸性氧化物。","Na₂O、CuO：金属氧化物，同时是碱性氧化物。","Al₂O₃：金属氧化物，但属于两性氧化物；CO含氧却是不成盐氧化物。"],"visualSteps":["氧化物","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"NaOH、H₂SO₄、Na₂CO₃虽含氧，但都含三种元素，不是氧化物。"},{"label":"酸","rule":"在水溶液中电离时，生成的阳离子全部是H⁺。确认后可分别按可电离H⁺数、电离程度、是否含氧分类。","examples":["HCl是一元强酸、无氧酸；H₂SO₄是二元强酸、含氧酸。","H₂CO₃是二元弱酸、含氧酸；CH₃COOH是一元弱酸、含氧酸。"],"visualSteps":["酸","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"盐酸是HCl的水溶液，属于混合物；HCl这种化合物才是被分类的对象。"},{"label":"碱","rule":"在水溶液中电离时，生成的阴离子全部是OH⁻。确认后可分别按OH⁻数、电离程度、溶解性分类。","examples":["NaOH是一元强碱、易溶碱；Ca(OH)₂是二元强碱、微溶碱。","Cu(OH)₂是二元弱碱、难溶碱；Fe(OH)₃是三元弱碱、难溶碱。"],"visualSteps":["碱","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"Al(OH)₃是两性氢氧化物，不能为了凑“三元碱”例子而忽略其两性边界。"},{"label":"盐","rule":"由金属阳离子或NH₄⁺与酸根阴离子构成。确认后可按是否保留可电离H或OH、以及溶解性继续分类。","examples":["NaCl、Na₂SO₄是正盐；NaHCO₃、NaHSO₄是酸式盐。","Cu₂(OH)₂CO₃、Mg(OH)Cl是碱式盐；NH₄Cl是铵盐。"],"visualSteps":["盐","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"盐不只指食盐；名称中也不一定出现“盐”字。"}]},{"title":"酸的分类1：按每个酸分子可电离的H⁺个数","summary":"数可电离的H，不是机械数化学式中所有H。","items":[{"label":"一元酸","rule":"每个酸分子最多可电离出1个H⁺。","examples":["HCl、HNO₃分别只有1个可电离H，是一元酸。","CH₃COOH虽有4个H，但只有羧基中的1个H可电离，所以是一元酸。"],"visualSteps":["一元酸","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"二元酸","rule":"每个酸分子最多可电离出2个H⁺。","examples":["H₂SO₄、H₂CO₃都是二元含氧酸。","H₂S是二元无氧弱酸。"],"visualSteps":["二元酸","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"多元酸","rule":"每个酸分子最多可电离出3个或更多H⁺。","examples":["H₃PO₄最多分步电离出3个H⁺，是三元酸。","柠檬酸C₆H₈O₇含3个羧基，题给结构时可判断为三元酸；它只作信息情境例，不要求死记。"],"visualSteps":["多元酸","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"不能只看化学式中H的下标判断元数；遇陌生物质必须按结构或题给电离式判断。"}]},{"title":"酸的分类2：按在水中的电离程度","summary":"强弱是酸本身的电离特征，不是某份溶液的浓或稀。","items":[{"label":"强酸","rule":"在水中按高中近似可看作完全电离。","examples":["HCl、HNO₃是常见一元强酸。","H₂SO₄在高中常规水溶液问题中按强酸处理。"],"visualSteps":["强酸","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"弱酸","rule":"在水中只部分电离，溶液中分子和离子共存。","examples":["H₂CO₃、H₂S、H₃PO₄是常见无机弱酸。","CH₃COOH是常见有机弱酸。"],"visualSteps":["弱酸","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"酸的分类3：按化学式中是否含氧","summary":"含氧与否不决定酸的强弱或元数。","items":[{"label":"含氧酸","rule":"化学式中含有氧元素的酸。","examples":["HNO₃、H₂SO₄是强含氧酸。","H₂CO₃、H₃PO₄、CH₃COOH是弱含氧酸。"],"visualSteps":["含氧酸","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"无氧酸","rule":"化学式中不含氧元素的酸。","examples":["HCl、HBr是强无氧酸。","H₂S是弱无氧酸。"],"visualSteps":["无氧酸","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"碱的分类1：按可产生的OH⁻个数","summary":"元数只看一个化学式单位可对应产生几个OH⁻；两性氢氧化物要单独辨别。","items":[{"label":"一元碱","rule":"一个化学式单位可对应产生1个OH⁻。","examples":["NaOH、KOH是一元强碱。","NH₃·H₂O在高中水溶液模型中按一元弱碱处理。"],"visualSteps":["一元碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"二元碱","rule":"一个化学式单位可对应产生2个OH⁻。","examples":["Ca(OH)₂、Ba(OH)₂是二元强碱。","Cu(OH)₂、Mg(OH)₂是二元弱碱。"],"visualSteps":["二元碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"三元碱与两性边界","rule":"Fe(OH)₃可按三元弱碱处理；遇Al(OH)₃应优先识别其两性，不机械把所有M(OH)₃都塞入同一结论。","examples":["Fe(OH)₃是三元弱碱、难溶碱。","Al(OH)₃既能与强酸反应，也能与强碱反应，是两性氢氧化物。"],"visualSteps":["三元碱与两性边界","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"常见三元碱例子少，准确性优先，不为凑数量引入超纲物质。"}]},{"title":"碱的分类2：按电离程度","summary":"强弱与溶解性是两条独立标准。","items":[{"label":"强碱","rule":"溶解进入水中的部分按高中近似可看作完全电离。","examples":["NaOH、KOH、Ba(OH)₂是常见强碱。","Ca(OH)₂虽微溶，但溶解部分电离完全，仍是强碱。"],"visualSteps":["强碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"弱碱","rule":"进入水中的部分不能按强碱完全电离模型处理，分子或难溶固体与离子之间存在平衡。","examples":["NH₃·H₂O是可溶的一元弱碱。","Cu(OH)₂、Fe(OH)₃是难溶弱碱。"],"visualSteps":["弱碱","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"碱的分类3：按溶解性","summary":"溶解性回答“能溶多少”，强弱回答“溶解后电离多少”。","items":[{"label":"易溶碱","rule":"在水中溶解度较大。","examples":["NaOH、KOH易溶于水。","Ba(OH)₂在中学定性分类中列入可溶碱。"],"visualSteps":["易溶碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"微溶碱","rule":"在水中只能溶解一部分，但不能由此推断为弱碱。","examples":["Ca(OH)₂是典型微溶强碱。","澄清石灰水是Ca(OH)₂溶液，石灰乳则是含未溶固体的混合物。"],"visualSteps":["微溶碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"难溶碱","rule":"在水中溶解度很小，常以沉淀出现。","examples":["Mg(OH)₂、Cu(OH)₂是难溶碱。","Fe(OH)₃是红褐色难溶碱。"],"visualSteps":["难溶碱","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"氧化物的分类1：按另一种组成元素","summary":"元素类别与氧化物的酸碱性质不能互相替代。","items":[{"label":"金属氧化物","rule":"由氧元素和一种金属元素组成。","examples":["Na₂O、CaO、CuO是金属氧化物和碱性氧化物。","Al₂O₃、ZnO也是金属氧化物，但属于两性氧化物。"],"visualSteps":["金属氧化物","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"非金属氧化物","rule":"由氧元素和一种非金属元素组成。","examples":["CO₂、SO₂、SO₃是非金属酸性氧化物。","CO、NO是非金属氧化物，但属于不成盐氧化物。"],"visualSteps":["非金属氧化物","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"氧化物的分类2：按酸碱性质","summary":"先满足氧化物定义，再看与酸、碱反应生成盐和水的性质。","items":[{"label":"酸性氧化物","rule":"能与碱反应生成盐和水的氧化物。","examples":["CO₂+2NaOH=Na₂CO₃+H₂O。","SO₂、SO₃也属于酸性氧化物。"],"visualSteps":["酸性氧化物","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"酸性氧化物不一定能直接与水生成对应酸，如SiO₂不能直接与水生成H₂SiO₃。"},{"label":"碱性氧化物","rule":"能与酸反应生成盐和水的氧化物。","examples":["Na₂O+2HCl=2NaCl+H₂O。","CaO、CuO也属于碱性氧化物。"],"visualSteps":["碱性氧化物","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"金属氧化物不一定都是碱性氧化物。"},{"label":"两性氧化物","rule":"既能与强酸反应，又能与强碱反应的氧化物。","examples":["Al₂O₃与盐酸反应生成AlCl₃和H₂O。","Al₂O₃、ZnO都能与强碱反应形成相应含氧酸盐体系。"],"visualSteps":["两性氧化物","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"不成盐氧化物","rule":"通常条件下不表现为与酸或碱生成盐和水。","examples":["CO、NO是不成盐氧化物。","CO、NO在本模块只按分类边界识别，不延伸陌生反应。"],"visualSteps":["不成盐氧化物","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"氧化物的分类3：普通氧化物与过氧化物边界","summary":"不能把氧元素化合价一律写成−2。","items":[{"label":"普通氧化物","rule":"氧元素通常为−2价。","examples":["Na₂O中O为−2价；CO₂中O为−2价。","Al₂O₃、SO₃中O也为−2价。"],"visualSteps":["普通氧化物","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"过氧化物","rule":"含过氧键，氧元素为−1价，反应规律不能照搬普通碱性氧化物。","examples":["Na₂O₂中O为−1价。","H₂O₂中O为−1价。"],"visualSteps":["过氧化物","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"盐的分类1：按酸中的H或碱中的OH是否完全被取代","summary":"三类名称来自组成，不能只看溶液酸碱性。","items":[{"label":"正盐","rule":"酸中可电离的H全部被金属或NH₄⁺取代，且化学式中不保留OH。","examples":["NaCl、Na₂SO₄是正盐。","Na₂CO₃、KNO₃、NH₄Cl也是正盐。"],"visualSteps":["正盐","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"酸式盐","rule":"多元酸中的可电离H只被部分取代，阴离子中仍保留可电离H。","examples":["NaHCO₃、NaHSO₄是酸式盐。","NaH₂PO₄、Na₂HPO₄也是酸式盐。"],"visualSteps":["酸式盐","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"酸式盐的水溶液不一定显酸性，例如NaHCO₃溶液可显碱性。"},{"label":"碱式盐","rule":"碱中的OH未被酸完全中和，盐的组成中仍保留OH。","examples":["Cu₂(OH)₂CO₃是碱式碳酸铜。","Mg(OH)Cl是碱式氯化镁，只作组成分类例子。"],"visualSteps":["碱式盐","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"盐的分类2：按水中溶解性","summary":"按教材溶解性规律判断；可溶、微溶、难溶不等于强弱电解质。","items":[{"label":"可溶性盐","rule":"在水中有较大溶解度。","examples":["NaCl、KNO₃可溶。","(NH₄)₂SO₄、Na₂CO₃可溶。"],"visualSteps":["可溶性盐","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"微溶性盐","rule":"溶解度介于可溶与难溶之间，定性题要服从题给条件和溶解性表。","examples":["CaSO₄常按微溶处理。","Ag₂SO₄在中学溶解性表中常列为微溶。"],"visualSteps":["微溶性盐","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"难溶性盐","rule":"在水中溶解度很小，常形成沉淀。","examples":["AgCl、BaSO₄是典型难溶盐。","CaCO₃、BaCO₃也是难溶盐。"],"visualSteps":["难溶性盐","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"横向分类：电解质先按定义判断","summary":"这条线只研究化合物；“导电”是现象，“产生可移动离子”才是原因。","items":[{"label":"电解质","rule":"在水溶液中或熔融状态下，能由物质本身产生可自由移动离子并导电的化合物。","examples":["HCl水溶液靠H⁺、Cl⁻导电；熔融NaCl靠Na⁺、Cl⁻导电。","固态NaCl有离子但离子不能自由移动，所以固态不导电，NaCl仍属于电解质。"],"visualSteps":["电解质","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"定义中的“水溶液中或熔融状态”只需至少一种状态满足；对象必须是化合物。"},{"label":"非电解质","rule":"在水溶液中和熔融状态下都不能由自身产生可自由移动离子的化合物。","examples":["蔗糖、乙醇溶于水后主要以分子存在，是非电解质。","CO₂、SO₂、NH₃物质本身不电离；它们与水反应形成的体系会产生离子。"],"visualSteps":["非电解质","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"既不是电解质也不是非电解质","rule":"单质和混合物不参加这组分类。","examples":["Cu、石墨能导电，但它们是单质，不能叫电解质。","盐酸、食盐水能导电，但它们是混合物，不能把整份溶液叫作电解质。"],"visualSteps":["既不是电解质也不是非电解质","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"电解质的五类常见来源","summary":"先判断具体化合物是否符合定义，再使用类别经验；不能把类别名称当作无条件结论。","items":[{"label":"1. 酸","rule":"酸进入水中产生H⁺和相应阴离子，属于电解质。","examples":["HCl、HNO₃、H₂SO₄是强电解质。","H₂CO₃、H₃PO₄、CH₃COOH是弱电解质。"],"visualSteps":["1. 酸","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"2. 碱","rule":"碱在水中产生金属阳离子或NH₄⁺模型中的相应阳离子以及OH⁻，属于电解质。","examples":["NaOH、KOH、Ba(OH)₂是强电解质。","NH₃·H₂O、Cu(OH)₂、Fe(OH)₃按弱电解质处理。"],"visualSteps":["2. 碱","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"3. 盐","rule":"盐溶于水或熔融时形成离子，属于电解质；难溶不等于非电解质。","examples":["NaCl、KNO₃、NH₄Cl是可溶盐和强电解质。","BaSO₄、CaCO₃虽难溶，溶解部分以离子存在，仍是电解质。"],"visualSteps":["3. 盐","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"4. 符合条件的离子型金属氧化物","rule":"常见离子型金属氧化物在熔融状态含可移动离子，可按电解质处理。","examples":["熔融Na₂O、MgO含可移动离子。","工业电解熔融Al₂O₃体系利用其离子导电；具体装置条件以后续课程为准。"],"visualSteps":["4. 符合条件的离子型金属氧化物","先看分类依据","再按定义判断","用例子与反例校验"],"caution":"不要把“金属氧化物”四个字直接当作无条件结论；先确认研究对象、结构和状态。"},{"label":"5. 水","rule":"水能极微弱地自电离，纯水中存在少量H⁺和OH⁻，因此H₂O是极弱电解质。","examples":["H₂O⇌H⁺+OH⁻表示水的自电离高中模型。","纯水导电性很弱，但“很弱”不等于完全没有离子。"],"visualSteps":["5. 水","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"电解质还可按电离程度分强、弱","summary":"强弱看电离或离解是否近似完全，不看溶液浓度，也不看溶解度大小。","items":[{"label":"强电解质","rule":"在水溶液中或熔融状态下近似完全生成离子。","examples":["HCl、HNO₃、H₂SO₄和NaOH、KOH是常见强电解质。","NaCl、KNO₃等可溶盐是强电解质；BaSO₄等难溶盐的已溶部分也完全离解。"],"visualSteps":["强电解质","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"弱电解质","rule":"在水中只部分电离，分子与离子共存并建立动态平衡。","examples":["CH₃COOH、H₂CO₃、H₃PO₄是弱酸和弱电解质。","NH₃·H₂O以及H₂O是弱电解质。"],"visualSteps":["弱电解质","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"四个不能互推","rule":"强弱、浓稀、溶解性、导电能力分别回答不同问题。","examples":["稀HCl仍是强酸和强电解质；浓CH₃COOH仍是弱酸和弱电解质。","Ca(OH)₂微溶但属强碱；BaSO₄难溶但仍按强电解质处理。"],"visualSteps":["四个不能互推","先看分类依据","再按定义判断","用例子与反例校验"]}]},{"title":"混合物中的分散系","summary":"溶液、胶体和浊液都是混合物，根本区别是分散质粒子大小。","items":[{"label":"溶液：通常小于1 nm","rule":"分散质以分子或离子形式存在，体系均一、透明、稳定，不产生丁达尔效应。","examples":["NaCl溶液、蔗糖溶液。","盐酸、CuSO₄溶液。"],"visualSteps":["溶液：通常小于1 nm","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"胶体：通常1～100 nm","rule":"胶体粒子能散射光，产生丁达尔效应；宏观看起来均一，但仍是混合物。","examples":["Fe(OH)₃胶体、淀粉胶体。","雾、烟、豆浆等可作常见胶体情境。"],"visualSteps":["胶体：通常1～100 nm","先看分类依据","再按定义判断","用例子与反例校验"]},{"label":"浊液：通常大于100 nm","rule":"粒子较大，体系通常不稳定，久置会沉降或分层。","examples":["泥水、石灰乳属于悬浊液。","油水混合物属于乳浊液。"],"visualSteps":["浊液：通常大于100 nm","先看分类依据","再按定义判断","用例子与反例校验"]}]}],"workedExamples":[{"substance":"H₂SO₄沿总树和三条酸分类轴定位","path":"一份纯H₂SO₄样品只含一种物质，所以是纯净物；含H、S、O三种元素，是化合物；属于无机化合物中的酸。它每个分子最多电离2个H⁺，是二元酸；高中常规水溶液中按强酸处理；含O，所以是含氧酸；同时属于强电解质。","labels":["纯净物→化合物","无机物→酸","二元/强/含氧","强电解质"]},{"substance":"Ca(OH)₂为什么能同时得到三个标签","path":"Ca(OH)₂属于碱；一个化学式单位可对应产生2个OH⁻，是二元碱；溶解部分近似完全电离，是强碱；在水中溶解度不大，是微溶碱。元数、强弱、溶解性三条轴互不替代。","labels":["二元碱","强碱","微溶碱","标准不能混用"]},{"substance":"NaCl固体不导电，为什么NaCl仍是电解质","path":"先确认NaCl是化合物。固态时Na⁺、Cl⁻被晶格固定，不能自由移动；熔融或溶于水后离子可以移动并导电，因此NaCl属于电解质。分类看规定状态下能否由自身产生可移动离子，不看固体此刻能否导电。","labels":["先看对象","固态离子固定","熔融/水溶可移动","电解质"]},{"substance":"CO₂与水形成的体系能导电，为什么CO₂仍是非电解质","path":"CO₂是化合物，但CO₂物质本身不电离；它与水反应形成的体系会产生少量H⁺、HCO₃⁻等离子。导电离子来自反应后的体系，不能据此把CO₂判为电解质。","labels":["追溯离子来源","反应体系产生离子","CO₂非电解质","不能只看导电"]}],"checkpoints":["我能从“物质”开始，一层一层判断混合物、纯净物、单质、化合物。","我能分别展开氧化物、酸、碱、盐的分类，并为每个结论说出分类依据。","我能区分酸碱的元数、强弱和溶解性，不会把三条标准混在一起。","我能解释电解质的五类常见来源，并判断单质、混合物为何退出分类。","我不会用“溶液能导电”直接判断溶质一定是电解质。","我不会为了套规律把Al(OH)₃当普通三元碱，或把所有金属氧化物都叫碱性氧化物。"],"scopeNote":"本卡只保留福建高中化学范围内的分类知识；陌生物质只在题给结构或信息足够时作为情境，不要求额外背诵。","sourceBasis":"依据普通高中化学课程标准和福建现行考试范围，以苏教版必修教材顺序校准；定义、分类轴和典型例子再与本地一轮复习资料及现有题库交叉核对。","visualSummary":{"kind":"tree","title":"物质分类总树","tree":{"label":"物质","children":[{"label":"混合物","children":[{"label":"分散系","children":[{"label":"溶液＜1 nm"},{"label":"胶体1～100 nm"},{"label":"浊液＞100 nm"}]}]},{"label":"纯净物","children":[{"label":"单质","children":[{"label":"金属单质"},{"label":"非金属单质"}]},{"label":"化合物","children":[{"label":"有机化合物"},{"label":"无机化合物","children":[{"label":"氧化物"},{"label":"酸"},{"label":"碱"},{"label":"盐"}]}]}]}]},"axes":[{"label":"化合物｜电离","items":["电解质","非电解质"]},{"label":"酸｜三条轴","items":["一/二/多元","强/弱","含氧/无氧"]},{"label":"碱｜三条轴","items":["一/二/三元","强/弱","易溶/微溶/难溶"]},{"label":"氧化物｜性质","items":["酸性","碱性","两性","不成盐"]},{"label":"盐｜组成","items":["正盐","酸式盐","碱式盐"]}]}}$classification$::jsonb,
    review_status = 'approved',
    updated_at = now()
where id = 'KC_H1_CLASSIFY' and skill_id = 'H1_CLASSIFY';

do $$
declare
  content jsonb;
  section_value jsonb;
  item_value jsonb;
  required_label text;
begin
  select structured_content into content
  from public.chem_knowledge_cards
  where id = 'KC_H1_CLASSIFY' and skill_id = 'H1_CLASSIFY' and review_status = 'approved';

  if content is null then raise exception 'H1_CLASSIFY knowledge card missing'; end if;
  if coalesce((content->>'version')::integer, 0) < 4 then raise exception 'H1_CLASSIFY version is below 4'; end if;
  if jsonb_array_length(coalesce(content->'sections', '[]'::jsonb)) < 12 then
    raise exception 'H1_CLASSIFY has fewer than 12 detailed sections';
  end if;

  foreach required_label in array array['氧化物','酸','碱','盐','一元酸','二元酸','多元酸','强酸','弱酸','一元碱','二元碱','三元碱与两性边界','强碱','弱碱','易溶碱','微溶碱','难溶碱','酸性氧化物','碱性氧化物','两性氧化物','不成盐氧化物','正盐','酸式盐','碱式盐','电解质的五类常见来源','非电解质','强电解质','弱电解质']::text[] loop
    if position(required_label in content::text) = 0 then
      raise exception 'H1_CLASSIFY missing required label: %', required_label;
    end if;
  end loop;

  for section_value in select value from jsonb_array_elements(content->'sections') loop
    if length(coalesce(section_value->>'title', '')) = 0 or length(coalesce(section_value->>'summary', '')) = 0 then
      raise exception 'H1_CLASSIFY contains a section without title or summary';
    end if;
    for item_value in select value from jsonb_array_elements(coalesce(section_value->'items', '[]'::jsonb)) loop
      if jsonb_array_length(coalesce(item_value->'examples', '[]'::jsonb)) < 2 then
        raise exception 'H1_CLASSIFY item has fewer than two examples: %', item_value->>'label';
      end if;
    end loop;
  end loop;

  if content::text like '%氧化还原%' then raise exception 'H1_CLASSIFY leaked untaught redox content'; end if;
  if content::text like '%所有金属氧化物都是%' then raise exception 'H1_CLASSIFY contains an absolute metal-oxide error'; end if;
  if content::text like '%能导电的物质都是电解质%' then raise exception 'H1_CLASSIFY contains a conductivity shortcut error'; end if;
end $$;
